import{_ as t,o as i,c as a,al as o}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Official PX4 Developer Kit Program","description":"","frontmatter":{},"headers":[],"relativePath":"ko/hardware/dev_kit_program.md","filePath":"ko/hardware/dev_kit_program.md"}'),r={name:"ko/hardware/dev_kit_program.md"};function n(l,e,s,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="official-px4-developer-kit-program" tabindex="-1">Official PX4 Developer Kit Program <a class="header-anchor" href="#official-px4-developer-kit-program" aria-label="Permalink to &quot;Official PX4 Developer Kit Program&quot;">​</a></h1><p>This topic explains how manufacturers can get a drone kit certified as an <em>Official PX4 Developer Kit</em>.</p><p>The PX4 community is growing quickly, and developers are frequently blocked on getting the right hardware into their hands. Too many options and configuration permutations also make it hard for maintainers to support the community well. Official PX4 Developer Kits solve this by establishing a foundational hardware reference for the ecosystem: kits that meet a defined standard for the bare-minimum components a PX4 developer needs to create modern applications, backed by the trust of the PX4 name.</p><p>In return, Dronecode puts its official weight behind qualifying products (see <a href="#what-you-get">What you get</a> below).</p><p>Currently certified kits are listed in <a href="./../dev_kits/">PX4 Developer Kits</a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>A kit qualifies when it meets all five requirements:</p><ol><li>A flight controller meeting the latest <a href="https://pixhawk.org/standards/" target="_blank" rel="noreferrer">Pixhawk standard</a>, or matching its capabilities</li><li>The latest stable PX4 release, pre-installed</li><li>Pre-assembled, or assembly that requires no technical skill (no soldering)</li><li>A guide, a focused tutorial, and a reference sheet included with the kit</li><li>Third-party build quality verification</li></ol><p>The reference sheet must ship printed, in the box: pinouts, connectors, and specs at a glance, with no screen required (<a href="https://docs.modalai.com/voxl2-d0014/" target="_blank" rel="noreferrer">example: ModalAI VOXL 2 reference sheet</a>). The guide and tutorial may ship as QR-code links.</p><h2 id="what-qualifying-looks-like-in-practice" tabindex="-1">What Qualifying Looks Like in Practice <a class="header-anchor" href="#what-qualifying-looks-like-in-practice" aria-label="Permalink to &quot;What Qualifying Looks Like in Practice&quot;">​</a></h2><p>The experience your kit must deliver:</p><ul><li><strong>Rapid start:</strong> No technical skill needed to get flying. Minimal or zero assembly, software pre-installed, documentation included.</li><li><strong>Room to extend:</strong> Ample headroom for performant code. The latest components, or space to expand.</li><li><strong>Current hardware:</strong> Latest-generation drone hardware, matching the newest Pixhawk standard or its capabilities.</li><li><strong>A modern companion computer:</strong> Able to offload compute from the flight controller MCU.</li><li><strong>Everything included:</strong> Bundled with the open source software and tools developers expect.</li><li><strong>Quality assurance:</strong> An available support channel or forum.</li></ul><h3 id="where-to-focus-the-companion-computer" tabindex="-1">Where to Focus: the Companion Computer <a class="header-anchor" href="#where-to-focus-the-companion-computer" aria-label="Permalink to &quot;Where to Focus: the Companion Computer&quot;">​</a></h3><p>The biggest differentiator for a kit is the companion computer and the tools developers can leverage on it:</p><ul><li><strong>MAVLink:</strong> A solid interface that can feed multiple targets, using <a href="https://mavsdk.mavlink.io/" target="_blank" rel="noreferrer">MAVSDK</a>, mission planning tools, or MAVROS.</li><li><strong>DDS &amp; ROS 2:</strong> Leverage the <a href="./../middleware/uxrce_dds">uXRCE-DDS</a> integration and expose the interface directly to the companion computer over a high-bandwidth link.</li><li><strong>Easy app deployment:</strong> Tools that help developers continuously test applications across the whole development lifecycle.</li><li><strong>LTE / WiFi:</strong> A competent network stack that reaches the cloud securely and efficiently.</li><li><strong>Great documentation:</strong> Publicly accessible docs, with ways to contribute back for continuous improvement.</li></ul><h2 id="what-you-get" tabindex="-1">What You Get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What You Get {#what-you-get}&quot;">​</a></h2><p>Kits accepted into the program receive:</p><ul><li><strong>Official endorsement:</strong> The <em>Official PX4 Developer Kit</em> designation, on your product and your marketing.</li><li><strong>PX4 website listing:</strong> A listing on the PX4 website and in this documentation, for standing presence in front of the entire community.</li><li><strong>Official promotion:</strong> A promotional announcement from official Dronecode accounts on social media.</li></ul><h2 id="eligibility" tabindex="-1">Eligibility <a class="header-anchor" href="#eligibility" aria-label="Permalink to &quot;Eligibility&quot;">​</a></h2><p>The program is open exclusively to <a href="https://dronecode.org/" target="_blank" rel="noreferrer">Dronecode Foundation</a> members. Active membership is required for the endorsement, the website listing, and the promotion.</p><p>To apply, or to discuss membership as a first step, <a href="https://dronecode.org/contact/" target="_blank" rel="noreferrer">contact Dronecode</a>.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../dev_kits/">PX4 Developer Kits</a></li><li><a href="./../hardware/board_support_guide">Manufacturer&#39;s Board Support Guide</a></li></ul>',23)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
